/** 渲染自适应（auto）镜头启用说明；无触发型镜头时为空串。 */
function renderAutoLensNote() {
  const auto = Object.entries(LENSES).filter(([, lens]) => lens.triggers);
  if (auto.length === 0) return '';
  return '   - Adaptive lenses (auto):\n' +
