      .map(([, lens]) => '   - If the scope touches any of [' + lens.triggers.join(', ') + '] and the "' + lens.title + '" lens is not already enabled, enable it for this run.')
      .join('\n');
}

/** 为启用的镜头构建本地审查工作流（PR 模式已删除）。 */
